// Procedural surface textures (own art, generated by code: no image files). One 128x128 RGBA layer per surface kind
// (scripts/bake_cells.mjs KIND), packed in one texture array so the whole world keeps a single program and draw call per cell.
// Each layer is a *detail* multiplier: its mean is normalised to 128 (x2 in the shader = 1.0), so the baked vertex colours stay
// the real colour and the texture only adds grain, joints and patterns. Alpha = 255, except salina: alpha = dike (crust) mask, and water (7): alpha = fine noise.
// Layers drawn untextured double as noise: 7 (water ripples), 15 (lamp heads -> world-space macro noise for the ground).
// Pure function (no three.js) so a node check can run it: makeSurfaceLayers() -> { size, layers, data: Uint8Array }

export const TEX_SIZE = 128, TEX_LAYERS = 16;
const N = TEX_SIZE;

const h32 = n => { n = Math.imul(n ^ (n >>> 16), 0x7feb352d); n = Math.imul(n ^ (n >>> 15), 0x846ca68b); return ((n ^ (n >>> 16)) >>> 0) / 4294967296; };
const h2 = (x, y, s) => h32(Math.imul(x, 374761393) + Math.imul(y, 668265263) + Math.imul(s, 982451653));
const mod = (a, p) => ((a % p) + p) % p;
/** tileable value noise: (x, y) in lattice units, period p lattice cells */
function vnoise(x, y, p, s) {
  const xi = Math.floor(x), yi = Math.floor(y), fx = x - xi, fy = y - yi, u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy);
  const a = h2(mod(xi, p), mod(yi, p), s), b = h2(mod(xi + 1, p), mod(yi, p), s), c = h2(mod(xi, p), mod(yi + 1, p), s), d = h2(mod(xi + 1, p), mod(yi + 1, p), s);
  return (a + (b - a) * u) * (1 - v) + (c + (d - c) * u) * v;
}
/** fbm over the tile: pixel (px, py), base period P lattice cells per tile, `oct` octaves -> ~0..1 */
function fbm(px, py, P, oct, s) {
  let sum = 0, amp = 0.5, tot = 0;
  for (let o = 0; o < oct; o++) { const p = P << o; sum += amp * vnoise(px / N * p, py / N * p, p, s + o * 17); tot += amp; amp *= 0.5; }
  return sum / tot;
}
const grain = (px, py, s) => h2(px, py, s);

// per-layer pixel functions -> [r, g, b] (relative; normalised afterwards) and optional alpha
const L = [];
L[0] = () => [1, 1, 1];
L[1] = (x, y) => { const n = fbm(x, y, 8, 4, 1), g = grain(x, y, 2); const v = 0.8 + 0.4 * n + (g > 0.86 ? 0.14 : g < 0.1 ? -0.12 : 0); return [v * 0.97, v * 1.03, v * 0.94]; };   // grass
L[2] = (x, y) => { const n = fbm(x, y, 6, 4, 3), s = 0.5 + 0.5 * Math.sin((y + 6 * n) / N * Math.PI * 2 * 6); const v = 0.86 + 0.16 * s + 0.24 * (n - 0.5) + 0.06 * (grain(x, y, 4) - 0.5); return [v * 1.02, v, v * 0.95]; };   // field furrows
L[3] = (x, y) => { const n = fbm(x, y, 6, 4, 5), g = grain(x, y, 6); const v = 0.7 + 0.6 * n ** 1.5 + (g > 0.9 ? 0.15 : 0); return [v, v * 1.02, v * 0.96]; };   // forest floor
L[4] = (x, y) => { const n = fbm(x, y, 8, 3, 7), v = 0.88 + 0.24 * n; return [v, v * 0.99, v * 0.97, 0]; };   // salina: mud grain only; pools / dikes come from the baked ortho colour (a repeated 2 x 2 pool tile was the visible grid)
L[5] = (x, y) => { const n = fbm(x, y, 4, 3, 9), r = Math.sin((x + y * 0.4 + 20 * n) / N * Math.PI * 2 * 10); const v = 0.95 + 0.06 * r + 0.1 * (grain(x, y, 10) - 0.5) + 0.1 * (n - 0.5); return [v, v, v * 0.97]; };   // sand ripples
L[6] = (x, y) => { const n = fbm(x, y, 10, 4, 11), g = grain(x, y, 12); const v = 0.8 + 0.4 * n + (g > 0.93 ? -0.25 : g < 0.04 ? 0.2 : 0); return [v, v * 0.97, v * 0.93]; };   // dirt + pebbles
L[7] = (x, y) => [fbm(x, y, 4, 4, 31), fbm(x, y, 4, 4, 32), fbm(x, y, 8, 3, 34), Math.round(fbm(x, y, 8, 3, 33) * 255)];   // water: tileable ripple noise (rg big, ba fine; the shader reads rg / ba)
L[8] = (x, y) => {   // paving: 1 m slabs (32 px), grout, per-slab tone
  const gx = x % 32, gy = y % 32, grout = gx < 2 || gy < 2, t = h2(x >> 5, y >> 5, 13), n = fbm(x, y, 8, 3, 14);
  const v = grout ? 0.68 : 0.92 + 0.14 * t + 0.12 * (n - 0.5); return [v, v * 0.99, v * 0.97];
};
L[9] = (x, y) => { const n = fbm(x, y, 4, 4, 15), g = grain(x, y, 16), c = Math.abs(fbm(x, y, 3, 3, 17) - 0.5) < 0.006; const v = 0.95 + 0.16 * (g - 0.5) + 0.14 * (n - 0.5) - (c ? 0.1 : 0); return [v, v, v * 1.01]; };   // asphalt
L[10] = (x, y) => { const n = fbm(x, y, 4, 4, 18), st = Math.max(0, 0.25 - y / N) * fbm(x, y, 16, 2, 19); const v = 0.96 + 0.1 * (n - 0.5) + 0.04 * (grain(x, y, 20) - 0.5) - 0.25 * st; return [v, v * 0.99, v * 0.97]; };   // plaster (y=0: floor line)
L[11] = L[10];
L[12] = (x, y) => {   // plinth: stone blocks in 2 courses, offset joints
  const row = (y / 64) | 0, gx = (x + (row & 1) * 32) % 64, gy = y % 64, joint = gx < 3 || gy < 3, t = h2(((x + (row & 1) * 32) / 64) | 0, row, 21), n = fbm(x, y, 8, 3, 22);
  const v = joint ? 0.65 : 0.9 + 0.18 * t + 0.16 * (n - 0.5); return [v, v * 0.98, v * 0.95];
};
L[13] = (x, y) => {   // curved clay tiles: 12 channels across, 8 overlapping courses up the slope
  const s = Math.abs(Math.sin(x / N * Math.PI * 12)), fy = (y * 8 / N) % 1, lap = fy < 0.12 ? 0.62 + fy * 2.5 : 1, t = h2((x * 12 / N) | 0, (y * 8 / N) | 0, 23);
  const v = (0.7 + 0.4 * Math.sqrt(s)) * lap * (0.92 + 0.16 * t); return [v * (1 + 0.08 * (t - 0.5)), v, v * 0.96];
};
L[14] = (x, y) => {   // azotea: 0.5 m square tiles (16 px) + damp stains
  const joint = x % 16 < 1 || y % 16 < 1, t = h2(x >> 4, y >> 4, 24), st = fbm(x, y, 4, 3, 25);
  const v = (joint ? 0.78 : 0.94 + 0.1 * t) * (0.9 + 0.2 * st); return [v, v * 0.98, v * 0.96];
};
L[15] = (x, y) => [fbm(x, y, 3, 4, 41), fbm(x, y, 4, 3, 42), 1];   // lamp heads draw untextured: this layer is the macro noise (r variation, g A/B blend mask)

export function makeSurfaceLayers() {
  const data = new Uint8Array(N * N * 4 * TEX_LAYERS), px = new Float32Array(N * N * 3);
  for (let l = 0; l < TEX_LAYERS; l++) {
    const f = L[l], o = l * N * N * 4, m = [0, 0, 0];
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
      const c = f(x, y), k = (y * N + x) * 3; for (let i = 0; i < 3; i++) { px[k + i] = c[i]; m[i] += c[i]; }
      data[o + (y * N + x) * 4 + 3] = c[3] ?? 255;
    }
    for (let i = 0; i < 3; i++) m[i] /= N * N;
    for (let p = 0; p < N * N; p++) for (let i = 0; i < 3; i++) data[o + p * 4 + i] = Math.max(0, Math.min(255, Math.round(px[p * 3 + i] / m[i] * 128)));   // mean -> 128 (= x1.0)
  }
  return { size: N, layers: TEX_LAYERS, data };
}
